  stmts := ARRAY_APPEND(:stmts,
    'INSERT INTO ' || :tgt || '.APP_CUSTOMIZATION (ID, CONFIG) '
 || 'SELECT ''default'', PARSE_JSON(''{"version":1}'') '
 || 'WHERE NOT EXISTS (SELECT 1 FROM ' || :tgt || '.APP_CUSTOMIZATION WHERE ID = ''default'')');

