  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''ML_MIGRATION_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ML_MIGRATION_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''ML_MIGRATION_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ML_MIGRATION_APP'' AND "comment"=''oneshot-source:05_ml_migration''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.ML_MIGRATION_APP FROM ''@__TARGET__.APP_STAGE/source/f6759c8f58a938ef/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:05_ml_migration''; ALTER STREAMLIT __TARGET__.ML_MIGRATION_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
